import type {
  ModelReq,
  // ImageEditInput,
  HunyuanGenerateImageInput,
  HunyuanGenerateImageOutput,
  HunyuanARGenerateImageInput,
  HunyuanARGenerateImageOutput,
  CloudbaseGenerateImageInput,
  CloudbaseGenerateImageOutput,
  // HunyuanEditImageInput,
  // HunyuanEditImageOutput,
} from '../type'
import { InvalidParamsError } from '../errors'

interface HunyuanImageGenerateFn {
  (input: HunyuanARGenerateImageInput): Promise<HunyuanARGenerateImageOutput>
  (input: HunyuanGenerateImageInput): Promise<HunyuanGenerateImageOutput>
}

type CloudbaseImageGenerateFn = (input: CloudbaseGenerateImageInput) => Promise<CloudbaseGenerateImageOutput>

type GenerateImageInput =
  | HunyuanARGenerateImageInput
  | HunyuanGenerateImageInput
  | CloudbaseGenerateImageInput

type GenerateImageOutput =
  | HunyuanARGenerateImageOutput
  | HunyuanGenerateImageOutput
  | CloudbaseGenerateImageOutput

type GenerateImageFn<TProvider> = TProvider extends 'hunyuan-image'
  ? HunyuanImageGenerateFn
  : TProvider extends 'cloudbase'
    ? CloudbaseImageGenerateFn
    : (input: unknown) => Promise<unknown>

export class DefaultImageModel<TProvider extends string> {
  /** 默认子路径，仅作为老 provider（''/hunyuan-image）的兜底，cloudbase 等新 provider 不支持兜底 */
  public defaultGenerateImageSubUrl = 'images/ar/generations'

  public generateImageSubUrlConfig: Record<string, Array<[RegExp, string]>> = {
    'hunyuan-image': [
      [/^hunyuan-image(-v[12](\..*)?)?$/, 'images/generations'],
    ],
    cloudbase: [
      [/^hy-image-v3\.5-preview$/, 'wand/hunyuan-image/v35-generation'],
    ],
  }

  /** 生成图片 */
  public generateImage: GenerateImageFn<TProvider>

  constructor(
    private req: ModelReq,
    public baseUrl: string,
    public provider: TProvider,
  ) {
    this.generateImage = this.generateImageImpl.bind(this) as GenerateImageFn<TProvider>
  }

  /** generateImage 的实际实现 */
  private async generateImageImpl(input: GenerateImageInput): Promise<GenerateImageOutput> {
    this.validateInput(input)

    const subUrl = this.resolveSubUrl(input)

    const res = (await this.req({
      url: this.getGenerateUrl(subUrl),
      data: input,
      stream: false,
    })) as GenerateImageOutput

    return res
  }

  /** 按 provider 执行各自的参数校验 */
  private validateInput(input: GenerateImageInput) {
    if (this.provider === '' || this.provider === 'hunyuan-image') {
      this.assertHunyuanInput(input)
    }
  }

  /** 当模型为 HY-Image-v3.0-I2I-ToB-v1.0.1 时，image_urls / images 最多只能有 1 个元素 */
  private assertHunyuanInput(input: GenerateImageInput) {
    if (!input || input.model !== 'HY-Image-v3.0-I2I-ToB-v1.0.1') return

    const { image_urls: imageUrls, images } = input

    if (imageUrls && imageUrls.length > 1) {
      throw new InvalidParamsError(
        '当模型为 HY-Image-v3.0-I2I-ToB-v1.0.1 时，image_urls 最多只能有 1 个元素',
        'image_urls',
      )
    }
    if (images && images.length > 1) {
      throw new InvalidParamsError(
        '当模型为 HY-Image-v3.0-I2I-ToB-v1.0.1 时，images 最多只能有 1 个元素',
        'images',
      )
    }
  }

  /**
   * 解析生成图片的子路径。
   * 老 provider（''/hunyuan-image）未命中路由时兜底到默认子路径；
   * cloudbase 等新 provider 不支持默认子路径，模型未配置路由时直接报错。
   */
  private resolveSubUrl(input: GenerateImageInput): string {
    const model = input && typeof input.model === 'string' ? input.model : undefined
    const subUrl = model ? this.getGenerateImageSubUrl(this.provider, model) : undefined

    if (subUrl) return subUrl

    if (this.provider === 'cloudbase') {
      throw new InvalidParamsError(
        `cloudbase provider 不支持的模型：${model ?? '(未指定)'}`,
        'model',
      )
    }

    return this.defaultGenerateImageSubUrl
  }

  private getGenerateUrl(subUrl: string) {
    return `${this.baseUrl}/${this.provider}/${subUrl}`
  }

  /**
   * 根据 provider 与 model 解析生成图片的子路径。
   * 按配置顺序用 RegExp 匹配，命中即返回对应 subUrl。
   */
  private getGenerateImageSubUrl(provider: string, model: string): string | undefined {
    const rules = this.generateImageSubUrlConfig[provider]
    if (!rules) return undefined

    for (const [pattern, subUrl] of rules) {
      if (pattern.test(model)) return subUrl
    }

    return undefined
  }
}
