import { Upload } from 'tus-js-client'
import { StorageError, StorageApiError, isStorageError } from './supabase/errors'
import { Http } from './http'
import { FileBody, Result, ResumableUploadOptions, ResumableUploadResult } from './types'
import { TusStoredUpload, selectUrlStorage } from './tus-url-storage'
import { createFetchHttpStack } from './tus-wx-http'
import { WxFileReader, statWxFileSize } from './tus-wx-file'
import { isWxMiniProgramEnv } from './wx-env'

const MB = 1024 * 1024
const MIN_CHUNK = 1 * MB
/** 6MiB 的 10 倍。单次网关请求体上限 100MiB，单片不打满。 */
const MAX_CHUNK = 60 * MB
/** 单个文件上限，1024 进制。 */
const MAX_FILE_SIZE = 100 * 1024 * MB
const MAX_PARTS = 10000
/** 小程序一次 readFile + wx.request 的单片上限。阶梯结果再封顶，避免整文件进内存。 */
export const WX_MAX_CHUNK = 4 * MB
const DEFAULT_CACHE_CONTROL = '3600'
const DEFAULT_RETRY_DELAYS = [0, 200, 500, 1500, 3000, 5000]
/** 小程序 TUS 单次 wx.request 超时。分片上传算进整次请求，不用实例默认的 15s。 */
const WX_TUS_TIMEOUT = 60 * 1000

interface PreparedFile {
  input: Blob | ArrayBufferView | string
  size: number
  contentType?: string
  cacheControl?: string
  metadata?: string
}

interface UploadContext {
  http: Http
  bucketId: string
  /** 已规整的对象路径。规整失败时由调用方在执行阶段抛出。 */
  resolveObjectName: () => string
  fileBody: FileBody
  options?: ResumableUploadOptions
  headers?: Record<string, string>
  shouldThrowOnError: boolean
}

function isNodeBuffer(value: unknown): value is { length: number } {
  const bufferCtor = (globalThis as { Buffer?: { isBuffer: (input: unknown) => boolean } }).Buffer
  return Boolean(bufferCtor && bufferCtor.isBuffer(value))
}

function asUploadError(error: unknown): Error {
  if (error instanceof Error) return error
  const wrapped = new Error('tus upload failed')
  const response = (error as { originalResponse?: { getStatus?: () => number } | null })?.originalResponse
  if (response) {
    (wrapped as { originalResponse?: typeof response }).originalResponse = response
  }
  return wrapped
}

function statusOf(error: unknown): number {
  const response = (error as { originalResponse?: { getStatus?: () => number } | null })?.originalResponse
  const status = response?.getStatus?.()
  return typeof status === 'number' ? status : 0
}

function toStorageError(error: unknown): StorageError {
  if (isStorageError(error)) return error
  const status = statusOf(error)
  const message = error instanceof Error ? error.message : String(error)
  if (status) return new StorageApiError(message, status, 'STORAGE_TUS_REQUEST_FAIL')
  return new StorageError(message)
}

/**
 * Studio 的阶梯分片：小文件 6MB，之后按 8 / 10 / 20 / 30 / 50 片加大单片。
 * 约 1.76GiB 起单片被钉在 60MB，片数继续增加。片数超过 10000 时抬高单片，但不超过 60MB。
 * 调用方传入 `chunkSize` 时同样限制在 1MB 到 60MB。
 */
export function planChunkSize(fileSize: number, requested?: number): number {
  if (requested !== undefined) return limitChunkSize(fileSize, requested)
  const fileSizeInMB = fileSize / MB
  let chunkSize: number
  if (fileSizeInMB < 30) chunkSize = 6 * MB
  else if (fileSizeInMB < 100) chunkSize = Math.floor(fileSize / 8)
  else if (fileSizeInMB < 500) chunkSize = Math.floor(fileSize / 10)
  else if (fileSizeInMB < 1024) chunkSize = Math.floor(fileSize / 20)
  else if (fileSizeInMB < 10 * 1024) chunkSize = Math.floor(fileSize / 30)
  else chunkSize = Math.floor(fileSize / 50)
  return limitChunkSize(fileSize, chunkSize)
}

/** 夹到 1MB–60MB。片数会超过 10000 时抬高单片，仍不超过 60MB。 */
function limitChunkSize(fileSize: number, chunkSize: number): number {
  let limited = Math.min(Math.max(chunkSize, MIN_CHUNK), MAX_CHUNK)
  if (fileSize > limited * MAX_PARTS) {
    limited = Math.min(Math.ceil(fileSize / MAX_PARTS), MAX_CHUNK)
  }
  return limited
}

/** 超过 100GiB，或按当前单片仍超过 10000 片时拒绝，不建 TUS 会话。 */
function assertResumableLimits(fileSize: number, chunkSize: number): void {
  if (fileSize > MAX_FILE_SIZE) {
    throw new StorageError('uploadResumable file exceeds 100GiB')
  }
  if (chunkSize <= 0 || fileSize > chunkSize * MAX_PARTS) {
    throw new StorageError('uploadResumable exceeds 10000 chunks')
  }
}

/** 小程序把阶梯结果再封顶到 {@link WX_MAX_CHUNK}。调用方传入的更小分片保持原样。 */
export function capChunkSize(fileSize: number, requested: number | undefined, wxMiniProgram: boolean): number {
  const planned = planChunkSize(fileSize, requested)
  if (!wxMiniProgram) return planned
  return Math.min(planned, WX_MAX_CHUNK)
}

/** 409 / 423 / 5xx / 网络错误重试；其它 4xx 不重试。 */
export function shouldRetryTusError(error: unknown): boolean {
  const status = statusOf(error)
  if (status === 409 || status === 423) return true
  if (status >= 400 && status < 500) return false
  return true
}

function extractFormData(source: FormData): { file: Blob; contentType?: string; cacheControl?: string; metadata?: string } {
  let file: Blob | undefined
  let fileCount = 0
  let contentType: string | undefined
  let cacheControl: string | undefined
  let metadata: string | undefined
  source.forEach((value, key) => {
    if (typeof Blob !== 'undefined' && value instanceof Blob) {
      file = value
      fileCount += 1
      return
    }
    if (key === 'contentType') contentType = String(value)
    else if (key === 'cacheControl') cacheControl = String(value)
    else if (key === 'metadata') metadata = String(value)
  })
  if (fileCount !== 1 || !file) {
    throw new StorageError('FormData must contain exactly one file')
  }
  return { file, contentType, cacheControl, metadata }
}

function prepareFile(fileBody: FileBody, options?: ResumableUploadOptions): PreparedFile {
  if (typeof FormData !== 'undefined' && fileBody instanceof FormData) {
    const extracted = extractFormData(fileBody)
    return {
      input: extracted.file,
      size: extracted.file.size,
      contentType: options?.contentType || extracted.contentType || extracted.file.type || undefined,
      cacheControl: options?.cacheControl ?? extracted.cacheControl,
      metadata: options?.metadata !== undefined ? JSON.stringify(options.metadata) : extracted.metadata,
    }
  }

  if (isNodeBuffer(fileBody)) {
    return {
      input: fileBody as ArrayBufferView,
      size: fileBody.length,
      contentType: options?.contentType,
    }
  }

  if (typeof Blob !== 'undefined' && fileBody instanceof Blob) {
    return {
      input: fileBody,
      size: fileBody.size,
      contentType: options?.contentType || fileBody.type || undefined,
    }
  }

  if (typeof fileBody === 'string') {
    return wrapBytes(new TextEncoder().encode(fileBody), options?.contentType)
  }

  if (fileBody instanceof ArrayBuffer) {
    return wrapBytes(new Uint8Array(fileBody), options?.contentType)
  }

  if (ArrayBuffer.isView(fileBody)) {
    return wrapBytes(new Uint8Array(fileBody.buffer, fileBody.byteOffset, fileBody.byteLength), options?.contentType)
  }

  throw new StorageError('uploadResumable requires a File, Blob, Buffer, string, or binary view with a known length')
}

async function prepareWxPath(filePath: string, options?: ResumableUploadOptions): Promise<PreparedFile> {
  const size = await statWxFileSize(filePath)
  return {
    input: filePath,
    size,
    contentType: options?.contentType,
  }
}

function wrapBytes(bytes: Uint8Array, contentType?: string): PreparedFile {
  if (typeof Blob !== 'undefined') {
    const blob = new Blob([bytes], contentType ? { type: contentType } : undefined)
    return { input: blob, size: blob.size, contentType }
  }
  return { input: bytes, size: bytes.byteLength, contentType }
}

function sameTarget(upload: { metadata?: { [key: string]: string } }, bucketId: string, objectName: string): boolean {
  return upload.metadata?.bucketName === bucketId && upload.metadata?.objectName === objectName
}

/**
 * 断点续传（thenable）。
 *
 * `await` 得到 `{ data, error }`。取消时调用 `abort(true)` 通知服务端终止会话。
 */
export class ResumableUpload implements PromiseLike<Result<ResumableUploadResult>> {
  private readonly ctx: UploadContext
  private run?: Promise<Result<ResumableUploadResult>>
  private upload: Upload | null = null
  private settled = false
  private failure: Error | null = null
  private pendingFail: ((error: Error) => void) | null = null

  constructor(ctx: UploadContext) {
    this.ctx = ctx
    const signal = ctx.options?.signal
    if (signal) {
      if (signal.aborted) {
        this.fail(new StorageError('The upload was aborted'))
      } else {
        const onAbort = () => {
          signal.removeEventListener('abort', onAbort)
          void this.abort(false)
        }
        signal.addEventListener('abort', onAbort)
      }
    }
  }

  then<TResult1 = Result<ResumableUploadResult>, TResult2 = never>(
    onfulfilled?: ((value: Result<ResumableUploadResult>) => TResult1 | PromiseLike<TResult1>) | null,
    onrejected?: ((reason: unknown) => TResult2 | PromiseLike<TResult2>) | null,
  ): PromiseLike<TResult1 | TResult2> {
    return this.start().then(onfulfilled, onrejected)
  }

  /**
   * 停止上传。
   *
   * @param terminate 为 true 时向服务端发 DELETE（termination）。已完成的上传服务端返回 405。
   */
  async abort(terminate = false): Promise<void> {
    if (!this.settled) {
      this.failure = new StorageError('The upload was aborted')
    }
    try {
      if (this.upload) await this.upload.abort(terminate)
    } finally {
      if (this.failure && !this.settled) this.fail(this.failure)
    }
  }

  private start(): Promise<Result<ResumableUploadResult>> {
    if (this.run === undefined) this.run = this.execute()
    return this.run
  }

  private fail(error: Error): void {
    if (this.settled) return
    this.settled = true
    this.failure = error
    this.pendingFail?.(error)
  }

  private async execute(): Promise<Result<ResumableUploadResult>> {
    try {
      if (this.settled) throw this.failure || new StorageError('The upload was aborted')

      const objectName = this.ctx.resolveObjectName()
      const wxPath = isWxMiniProgramEnv() && typeof this.ctx.fileBody === 'string'
        ? this.ctx.fileBody
        : undefined
      const prepared = wxPath
        ? await prepareWxPath(wxPath, this.ctx.options)
        : prepareFile(this.ctx.fileBody, this.ctx.options)
      const chunkSize = capChunkSize(prepared.size, this.ctx.options?.chunkSize, Boolean(wxPath))
      assertResumableLimits(prepared.size, chunkSize)
      const cacheControl = prepared.cacheControl ?? this.ctx.options?.cacheControl ?? DEFAULT_CACHE_CONTROL
      const contentType = prepared.contentType ?? this.ctx.options?.contentType
      const metadata: Record<string, string> = {
        bucketName: this.ctx.bucketId,
        objectName,
      }
      if (contentType) metadata.contentType = contentType
      if (cacheControl) metadata.cacheControl = String(cacheControl)
      const userMetadata = prepared.metadata ?? (
        this.ctx.options?.metadata !== undefined ? JSON.stringify(this.ctx.options.metadata) : undefined
      )
      if (userMetadata !== undefined) metadata.metadata = userMetadata

      const token = this.ctx.options?.token
      const endpoint = this.ctx.http.buildUrl(token ? '/upload/resumable/sign' : '/upload/resumable')
      const headers: Record<string, string> = { ...(this.ctx.headers || {}), ...(this.ctx.options?.headers || {}) }
      delete headers.Authorization
      delete headers.authorization
      if (this.ctx.options?.upsert) headers['x-upsert'] = 'true'

      const urlStorage = selectUrlStorage(this.ctx.options?.urlStorage)
      const { request } = this.ctx.http.ctx
      const upload = new Upload(prepared.input as Blob, {
        endpoint,
        headers,
        metadata,
        chunkSize,
        retryDelays: this.ctx.options?.retryDelays ?? DEFAULT_RETRY_DELAYS,
        uploadDataDuringCreation: prepared.size <= chunkSize,
        removeFingerprintOnSuccess: true,
        ...(wxPath ? {
          httpStack: createFetchHttpStack(options => request.fetch({
            ...options,
            timeout: WX_TUS_TIMEOUT,
          })),
          fileReader: new WxFileReader(),
          fingerprint: (_file, uploadOptions) => Promise.resolve(['tus-wx', wxPath, String(prepared.size), uploadOptions?.endpoint || ''].join('-')),
        } : {}),
        ...(urlStorage ? { urlStorage } : {}),
        onProgress: (bytesUploaded, bytesTotal) => {
          this.ctx.options?.onProgress?.(bytesUploaded, bytesTotal)
        },
        onBeforeRequest: async (req) => {
          if (token) {
            req.setHeader('x-signature', token)
            return
          }
          const accessToken = await this.ctx.http.ctx.request.getAccessToken()
          if (accessToken) req.setHeader('Authorization', `Bearer ${accessToken}`)
        },
        onShouldRetry: error => shouldRetryTusError(error),
      })
      this.upload = upload
      if (this.settled) {
        await upload.abort(false)
        throw this.failure || new StorageError('The upload was aborted')
      }

      try {
        const previous = await upload.findPreviousUploads()
        const match = previous.find(item => sameTarget(item, this.ctx.bucketId, objectName))
        if (match) upload.resumeFromPreviousUpload(match)
      } catch (error) {
        // 流或无法计算指纹时 tus 会拒绝查找；这种输入本来也不能跨调用续传，直接新建会话。
        if (!(error instanceof Error) || !/fingerprint/i.test(error.message)) throw error
      }

      const result = await new Promise<ResumableUploadResult>((resolve, reject) => {
        this.pendingFail = reject
        if (this.settled) {
          reject(this.failure || new StorageError('The upload was aborted'))
          return
        }
        upload.options.onSuccess = () => {
          if (this.settled) return
          this.settled = true
          resolve({
            path: objectName,
            fullPath: `${this.ctx.bucketId}/${objectName}`,
            uploadUrl: upload.url,
            size: prepared.size,
          })
        }
        upload.options.onError = (error) => {
          const normalized = asUploadError(error)
          void this.dropExpired(upload, objectName, normalized).finally(() => {
            this.fail(normalized)
          })
        }
        upload.start()
      })

      return { data: result, error: null }
    } catch (error) {
      const storageError = toStorageError(error)
      if (this.ctx.shouldThrowOnError) throw storageError
      return { data: null, error: storageError }
    }
  }

  /** PATCH 得到 410 / 404 时清掉会话书签，下次调用会重新 POST。HEAD 阶段的 4xx 由 tus 自己删除。 */
  private async dropExpired(upload: Upload, objectName: string, error: unknown): Promise<void> {
    const status = statusOf(error)
    if (status !== 410 && status !== 404) return
    const storage = upload.options.urlStorage
    if (!storage) return
    try {
      const previous = await upload.findPreviousUploads()
      await Promise.all(previous.filter(item => sameTarget(item, this.ctx.bucketId, objectName)).map((item) => {
        const key = (item as TusStoredUpload).urlStorageKey
        return key ? storage.removeUpload(key) : Promise.resolve()
      }))
    } catch {
      // 清书签失败不影响本次错误返回。
    }
  }
}
