import { getWx, isWxMiniProgramEnv } from './wx-env'

/**
 * 进程内的 TUS 会话地址存储。
 *
 * 浏览器里 `tus-js-client` 会把「文件指纹 → 上传 URL」写进 `localStorage`，刷新页面后还能续传。
 * Node 构建的 tus 默认是空存储，写了就丢，同进程里下一次 `uploadResumable` 也找不到上次的 URL。
 * 这里补一份同样键结构（`tus::{fingerprint}::{id}`）的内存表，活到进程结束，不落盘。
 * 小程序没有可枚举的 `window.localStorage`，用微信存储做同样的键。
 */
export interface TusStoredUpload {
  size: number | null
  metadata: { [key: string]: string }
  creationTime: string
  urlStorageKey?: string
  uploadUrl?: string | null
  parallelUploadUrls?: string[] | null
}

export class MemoryUrlStorage {
  private records = new Map<string, TusStoredUpload>()

  findAllUploads(): Promise<TusStoredUpload[]> {
    return Promise.resolve(this.findByPrefix('tus::'))
  }

  findUploadsByFingerprint(fingerprint: string): Promise<TusStoredUpload[]> {
    if (!fingerprint) return Promise.resolve([])
    return Promise.resolve(this.findByPrefix(`tus::${fingerprint}::`))
  }

  removeUpload(urlStorageKey: string): Promise<void> {
    this.records.delete(urlStorageKey)
    return Promise.resolve()
  }

  addUpload(fingerprint: string, upload: TusStoredUpload): Promise<string> {
    const id = Math.round(Math.random() * 1e12)
    const key = `tus::${fingerprint}::${id}`
    this.records.set(key, { ...upload })
    return Promise.resolve(key)
  }

  private findByPrefix(prefix: string): TusStoredUpload[] {
    const results: TusStoredUpload[] = []
    this.records.forEach((upload, key) => {
      if (key.indexOf(prefix) !== 0) return
      results.push({ ...upload, urlStorageKey: key })
    })
    return results
  }
}

/** 整个进程共用一份。同一次进程里再次上传同一文件可以找回会话 URL。 */
export const processUrlStorage = new MemoryUrlStorage()

const TUS_KEY_PREFIX = 'tus::'

/**
 * 小程序会话书签。tus 的 WebStorage 实现写死全局 `localStorage`，并且靠 `length` / `key(i)` 扫描，
 * 不能直接把 `wx` 存储对象塞进去。键结构与浏览器一致，枚举走 `getStorageInfoSync().keys`。
 */
export class WxStorageUrlStorage implements TusUrlStorage {
  findAllUploads(): Promise<TusStoredUpload[]> {
    return Promise.resolve(this.findByPrefix(TUS_KEY_PREFIX))
  }

  findUploadsByFingerprint(fingerprint: string): Promise<TusStoredUpload[]> {
    if (!fingerprint) return Promise.resolve([])
    return Promise.resolve(this.findByPrefix(`${TUS_KEY_PREFIX}${fingerprint}::`))
  }

  removeUpload(urlStorageKey: string): Promise<void> {
    getWx()?.removeStorageSync?.(urlStorageKey)
    return Promise.resolve()
  }

  addUpload(fingerprint: string, upload: TusStoredUpload): Promise<string> {
    const id = Math.round(Math.random() * 1e12)
    const key = `${TUS_KEY_PREFIX}${fingerprint}::${id}`
    getWx()?.setStorageSync?.(key, JSON.stringify(upload))
    return Promise.resolve(key)
  }

  private findByPrefix(prefix: string): TusStoredUpload[] {
    const wx = getWx()
    const keys = wx?.getStorageInfoSync?.()?.keys || []
    const results: TusStoredUpload[] = []
    keys.forEach((key) => {
      if (key.indexOf(prefix) !== 0) return
      try {
        const raw = wx?.getStorageSync?.(key)
        if (raw === null || raw === undefined || raw === '') return
        const upload = typeof raw === 'string' ? JSON.parse(raw) as TusStoredUpload : raw as TusStoredUpload
        if (!upload || typeof upload !== 'object') return
        results.push({ ...upload, urlStorageKey: key })
      } catch {
        // 坏数据不影响其余会话。
      }
    })
    return results
  }
}

/** 小程序进程共用一份，书签落在微信存储里，冷启动还能找回。 */
export const wxStorageUrlStorage = new WxStorageUrlStorage()

/** 浏览器有可用的 `window.localStorage` 时，把存储留给 tus 自己的 Web Storage 实现。 */
/** tus `urlStorage` 的最小结构。浏览器默认实现和进程内实现都满足它。 */
export interface TusUrlStorage {
  findAllUploads(): Promise<TusStoredUpload[]>
  findUploadsByFingerprint(fingerprint: string): Promise<TusStoredUpload[]>
  removeUpload(urlStorageKey: string): Promise<void>
  addUpload(fingerprint: string, upload: TusStoredUpload): Promise<string>
}

export function hasBrowserLocalStorage(): boolean {
  try {
    return typeof window !== 'undefined' && typeof window.localStorage?.setItem === 'function'
  } catch {
    return false
  }
}

/**
 * 选择会话地址存储。
 *
 * 调用方传入的优先。小程序用微信存储。浏览器走 tus 默认的 `localStorage`
 * （这里返回 `undefined`，不要用 `undefined` 覆盖 tus 的默认值）。
 * Node / CLI 用进程内内存表。
 */
export function selectUrlStorage(
  explicit?: TusUrlStorage,
  browserStorage = hasBrowserLocalStorage(),
  wxMiniProgram = isWxMiniProgramEnv(),
): TusUrlStorage | undefined {
  if (explicit) return explicit
  if (wxMiniProgram) return wxStorageUrlStorage
  if (browserStorage) return undefined
  return processUrlStorage
}
